#include <cuda_runtime.h>
#include <vector>
#include <algorithm>
#define main legacy_main
#include "../split-cuda/main.cu"
#undef main
#define CK(x) do{auto e=(x);if(e!=cudaSuccess){fprintf(stderr,"%s\n",cudaGetErrorString(e));exit(1);}}while(0)
int main(int argc,char**argv){int n=65536,repeat=argc>1?atoi(argv[1]):100;std::vector<unsigned>input(n),expected,got(n);srand(512);for(int i=0;i<n;i++)input[i]=rand()%16;expected=input;for(int i=0;i<n;i+=512)std::sort(expected.begin()+i,expected.begin()+i+512);unsigned *src,*dst;CK(cudaMalloc(&src,n*4));CK(cudaMalloc(&dst,n*4));CK(cudaMemcpy(src,input.data(),n*4,cudaMemcpyHostToDevice));auto launch=[&](){radixSortBlocksKeysK<<<n/512,128>>>(src,dst,4,0);};launch();CK(cudaDeviceSynchronize());bool all=true;for(int trial=1;trial<=5;trial++){CK(cudaMemset(dst,0,n*4));CK(cudaDeviceSynchronize());auto t0=std::chrono::steady_clock::now();for(int k=0;k<repeat;k++)launch();CK(cudaDeviceSynchronize());double elapsed=std::chrono::duration<double>(std::chrono::steady_clock::now()-t0).count()/repeat;CK(cudaMemcpy(got.data(),dst,n*4,cudaMemcpyDeviceToHost));int ma=0;for(int i=0;i<n;i++)ma=std::max(ma,abs(int(got[i])-int(expected[i])));bool ok=ma==0;all&=ok;char file[100];sprintf(file,"split_trial%d.bin",trial);FILE*f=fopen(file,"wb");fwrite(got.data(),4,n,f);fclose(f);printf("STUDY_TRIAL {\"trial\":%d,\"time_seconds\":%.12g,\"correct\":%s,\"checked_values\":%d,\"max_abs_error\":%d,\"max_rel_error\":0,\"timing_region\":\"block512_sort_kernel_only_per_repeat\",\"jit_excluded\":true,\"internal_repeats\":%d,\"output_artifact\":{\"path\":\"%s\",\"dtype\":\"uint32\",\"count\":%d,\"byte_order\":\"little\"}}\n",trial,elapsed,ok?"true":"false",n,ma,repeat,file,n);}CK(cudaFree(src));CK(cudaFree(dst));puts(all?"PASS":"FAIL");return all?0:1;}
